pub fn myfun(a: &mut Vec<i32>, sum: &mut Vec<i32>, N: i32) {
    // Convert N to usize for indexing
    let n = N as usize;

    // Fill `a` so that a[i] = i % 3
    for i in 0..n {
        a[i] = (i % 3) as i32;
    }

    // Initialize the accumulator at index 0
    sum[0] = 0;

    // Accumulate values from a[1] to a[n-1]
    for i in 1..n {
        sum[0] += a[i];
    }
}

